bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK_BUTTON_BOT_DOWN; exit 61; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import{readFileSync}from'node:fs';
import{createTelegramBotApi}from'./src/telegram/botApi.mjs';
import{createCreatorTelegramFetch}from'./src/runtime/creatorEgress.mjs';
const e=process.env;const id='sp_76f23430d1c29ca355960a95',chat=-1002373696859,thread=4640;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:6000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try{
 const q=await pool.query("SELECT p.title,p.pack_name,p.kind,p.status AS product_status,p.price_stars,p.management_fee_bps,p.fee_terms_accepted_at,t.status AS post_status,t.chat_id,t.message_thread_id,t.telegram_message_id FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[id]);
 if(q.rowCount!==1)throw Error('STK_BUTTON_PRODUCT_NOT_UNIQUE');
 const p=q.rows[0],msg=Number(p.telegram_message_id);
 if(p.product_status!=='published'||p.post_status!=='sent'||Number(p.price_stars)!==50||
 Number(p.management_fee_bps)!==3000||!p.fee_terms_accepted_at||Number(p.chat_id)!==chat||
 Number(p.message_thread_id)!==thread||msg<=4664||!['regular','custom_emoji'].includes(p.kind)||
 typeof p.pack_name!=='string'||!/^[A-Za-z0-9_]{1,64}$/.test(p.pack_name))
 throw Error('STK_BUTTON_PRODUCT_RECEIPT_INVALID');
 const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const api=createTelegramBotApi({token,fetchImpl:outgoing.fetch,timeoutMs:25000});
 const me=await api('getMe',{});
 if(me?.is_bot!==true||String(me.username).toLowerCase()!=='createvdobot')throw Error('STK_BUTTON_OWNER_INVALID');
 const set=await api('getStickerSet',{name:p.pack_name});
 if(set?.name!==p.pack_name||!Array.isArray(set.stickers)||set.stickers.length<1)throw Error('STK_BUTTON_PUBLIC_PACK_UNAVAILABLE');
 const pin=JSON.parse(readFileSync('/var/lib/videobot/sticker-entry/group2373696859_thread4640.json','utf8'));
 if(pin.status!=='pinned_ack'||Number(pin.message_id)===msg||Number(pin.thread_id)!==thread)throw Error('STK_BUTTON_PIN_CHANGED');
 const markup={inline_keyboard:[
 [{text:'🎨 パック全体を見る',url:'https://t.me/'+(p.kind==='custom_emoji'?'addemoji/':'addstickers/')+p.pack_name}],
 [{text:'⭐ Starsで購入',url:'https://t.me/CreateVdobot?start=buy_'+id}]
 ]};
 const result=await api('editMessageReplyMarkup',{chat_id:chat,message_id:msg,reply_markup:markup});
 if(!(result?.alreadyCurrent===true||result?.message_id===msg))throw Error('STK_BUTTON_TELEGRAM_EDIT_UNVERIFIED');
 console.log('STK_BUTTON_SAME_POST_UPDATED=PASS');
 console.log('STK_BUTTON_NATIVE_FULL_PACK_LINK=PASS');
 console.log('STK_BUTTON_STARS_DM_ENTRY=PASS');
 console.log('STK_BUTTON_MESSAGE_ID='+msg);
}finally{await outgoing.close();await pool.end();}
NODE
